# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.43.0/ankra-cli-darwin-arm64"
      sha256 "61ad7e274e3490534b31ad11404361434e28f8b2bc5cc5db139123ca66b80339"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.43.0/ankra-cli-darwin-amd64"
      sha256 "96558362e6a4f51f0e9345ad23d01d64459eb479e033db67708d0057dd4b63a1"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.43.0/ankra-cli-linux-arm64"
      sha256 "15cb193ec41e651efbf0e3fe106760cca15ed96f03fd6a200222d03bd73b197d"
    end
    on_intel do
